predicted_sql:
SELECT COALESCE(SUM(CASE WHEN Country='CZE' THEN 1 ELSE 0 END),0) - COALESCE(SUM(CASE WHEN Country='SVK' THEN 1 ELSE 0 END),0) AS difference
FROM gasstations
WHERE Segment = 'discount' AND Country IN ('CZE','SVK');

SELECT first_name || ' ' || last_name AS full_name
FROM member
WHERE zip BETWEEN 60001 AND 62999;

SELECT COALESCE(SUM(CASE WHEN SUBSTR(event.event_date,1,4) = '2019' THEN budget.spent END), 0) - COALESCE(SUM(CASE WHEN SUBSTR(event.event_date,1,4) = '2020' THEN budget.spent END), 0) AS difference
FROM budget
JOIN event ON budget.link_to_event = event.event_id;

SELECT DISTINCT Patient.ID AS ID, (CAST(strftime('%Y','now') AS INTEGER) - CAST(strftime('%Y', Patient.Birthday) AS INTEGER)) AS age
FROM Examination JOIN Patient ON Examination.ID = Patient.ID
WHERE Examination.RVVT = '+' AND Patient.Birthday IS NOT NULL;
